create table if not exists public.social_connections (id uuid primary key default gen_random_uuid(), platform text not null default 'meta', external_user_id text, external_user_name text, business_id text, business_name text, access_token_enc text, token_expires_at timestamptz, scopes text[], default_page_id text, default_instagram_id text, default_ad_account_id text, default_ad_instagram_id text, default_ad_instagram_username text, status text not null default 'connected', last_synced_at timestamptz, connected_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (platform));
create table if not exists public.social_pages (id uuid primary key default gen_random_uuid(), platform text not null default 'meta', connection_id uuid not null references public.social_connections(id) on delete cascade, page_id text not null, page_name text, category text, picture_url text, page_token_enc text, instagram_id text, instagram_username text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (connection_id, page_id));
create table if not exists public.social_ad_accounts (id uuid primary key default gen_random_uuid(), platform text not null default 'meta', connection_id uuid not null references public.social_connections(id) on delete cascade, ad_account_id text not null, name text, currency text, timezone_name text, account_status text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (connection_id, ad_account_id));
create table if not exists public.social_custom_audiences (id uuid primary key default gen_random_uuid(), platform text not null default 'meta', connection_id uuid, ad_account_id text not null, external_id text unique, name text not null, description text, source text not null default 'customer_list' check (source in ('customer_list')), origin text not null check (origin in ('file','list_view')), origin_ref text, identifier_schema text[] not null default '{EMAIL,PHONE}', row_count int not null default 0, invalid_count int not null default 0, duplicate_count int not null default 0, status text not null default 'ready' check (status in ('uploading','ready','failed')), meta_status jsonb not null default '{}'::jsonb, error text, created_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.social_campaigns (id uuid primary key default gen_random_uuid(), platform text not null default 'meta', connection_id uuid references public.social_connections(id) on delete set null, ad_account_id text, name text not null, objective text not null default 'awareness', buying_type text not null default 'auction', budget_type text not null default 'daily', budget_amount numeric not null default 0, status text not null default 'draft', special_ad_categories text[] not null default '{}', special_ad_category_country text[], bid_strategy text, spend_cap numeric, meta_effective_status text, start_date timestamptz, end_date timestamptz, external_id text, published_at timestamptz, last_synced_at timestamptz, created_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.social_ad_sets (id uuid primary key default gen_random_uuid(), platform text not null default 'meta', campaign_id uuid not null references public.social_campaigns(id) on delete cascade, name text not null, page_id text, instagram_id text, budget_type text not null default 'daily', budget_amount numeric, start_at timestamptz, end_at timestamptz, timezone_name text, placements jsonb not null default '[]'::jsonb, targeting jsonb not null default '{}'::jsonb, optimization_goal text, billing_event text, bid_strategy text, bid_amount numeric check (bid_amount is null or bid_amount > 0), status text not null default 'paused', external_id text, published_at timestamptz, last_synced_at timestamptz, custom_audience_id uuid references public.social_custom_audiences(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists social_ad_sets_custom_audience_idx on public.social_ad_sets (custom_audience_id);
create table if not exists public.social_ads (id uuid primary key default gen_random_uuid(), platform text not null default 'meta', ad_set_id uuid not null references public.social_ad_sets(id) on delete cascade, name text not null, creative_type text not null default 'single_image', media jsonb not null default '[]'::jsonb, headline text, primary_text text, description text, destination_url text, display_link text, call_to_action text, lead_form_id text, utm_parameters text, status text not null default 'draft', external_id text, creative_external_id text, format text not null default 'single' check (format in ('single','carousel')), destination_enabled boolean not null default true, ai_media boolean not null default false, multi_advertiser boolean not null default true, instagram_user_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.social_posts (id uuid primary key default gen_random_uuid(), platform text not null default 'meta', connection_id uuid references public.social_connections(id) on delete set null, post_type text not null default 'text', message text, media_url text, destination text not null default 'facebook', page_id text, instagram_id text, scheduled_at timestamptz, status text not null default 'draft', facebook_post_id text, instagram_post_id text, error_message text, published_at timestamptz, created_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.social_insights (id uuid primary key default gen_random_uuid(), platform text not null default 'meta', entity_type text not null, entity_id uuid, external_id text, stat_date date not null, reach bigint not null default 0, impressions bigint not null default 0, clicks bigint not null default 0, leads bigint not null default 0, purchases bigint not null default 0, conversions bigint not null default 0, spend numeric not null default 0, revenue numeric not null default 0, raw jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (entity_type, entity_id, stat_date));
create table if not exists public.social_lead_forms (id uuid primary key default gen_random_uuid(), platform text not null default 'meta', connection_id uuid, page_id text not null, external_id text unique, name text not null, questions jsonb not null default '[]'::jsonb, privacy_policy_url text, privacy_link_text text, follow_up_action_url text, thank_you_page jsonb, context_card jsonb, locale text not null default 'EN_US', is_optimized_for_quality boolean not null default false, block_display_for_non_targeted_viewer boolean not null default false, status text not null default 'ACTIVE', leads_count int not null default 0, imported boolean not null default false, created_by uuid, draft_payload jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists social_lead_forms_page_idx on public.social_lead_forms (page_id);
create table if not exists public.social_lead_submissions (id uuid primary key default gen_random_uuid(), platform text not null default 'meta', external_id text not null unique, form_external_id text, ad_external_id text, ad_id uuid, lead_id uuid references public.leads(id) on delete set null, created_time timestamptz, is_organic boolean, field_data jsonb not null default '[]'::jsonb, created_at timestamptz not null default now());
create index if not exists social_lead_submissions_form_idx on public.social_lead_submissions (form_external_id);
create table if not exists public.meta_api_diagnostics (id uuid primary key default gen_random_uuid(), user_id uuid, connection_id uuid, ad_account_id text, test_category text not null, test_name text not null, http_method text not null default 'GET', endpoint text, status text not null, meta_error_code text, meta_error_message text, http_status int, duration_ms int, records_returned int, created_at timestamptz not null default now());
create index if not exists meta_api_diagnostics_created_idx on public.meta_api_diagnostics (created_at desc);
create table if not exists public.meta_api_diagnostic_test_objects (id uuid primary key default gen_random_uuid(), user_id uuid, connection_id uuid, ad_account_id text, object_type text not null, external_id text not null, name text, cleaned_up_at timestamptz, created_at timestamptz not null default now());

drop trigger if exists social_connections_updated_at on public.social_connections;
create trigger social_connections_updated_at before update on public.social_connections for each row execute function public.comms_set_updated_at();
