drop trigger if exists social_ad_sets_updated_at on public.social_ad_sets;
create trigger social_ad_sets_updated_at before update on public.social_ad_sets for each row execute function public.comms_set_updated_at();
drop trigger if exists social_ads_updated_at on public.social_ads;
