drop trigger if exists social_insights_updated_at on public.social_insights;
create trigger social_insights_updated_at before update on public.social_insights for each row execute function public.comms_set_updated_at();
drop trigger if exists social_lead_forms_updated_at on public.social_lead_forms;
create trigger social_lead_forms_updated_at before update on public.social_lead_forms for each row execute function public.comms_set_updated_at();

-- grants
revoke all on public.social_connections from authenticated;
revoke all on public.social_pages from authenticated;
grant select (id, platform, external_user_id, external_user_name, business_id, business_name, token_expires_at, scopes, default_page_id, default_instagram_id, default_ad_account_id, default_ad_instagram_id, default_ad_instagram_username, status, last_synced_at, connected_by, created_at, updated_at) on public.social_connections to authenticated;
grant update (default_page_id, default_instagram_id, default_ad_account_id, default_ad_instagram_id, default_ad_instagram_username) on public.social_connections to authenticated;
grant select (id, platform, connection_id, page_id, page_name, category, picture_url, instagram_id, instagram_username, created_at, updated_at) on public.social_pages to authenticated;
grant select on public.social_ad_accounts, public.social_custom_audiences, public.social_insights, public.social_lead_forms, public.social_lead_submissions, public.meta_api_diagnostics, public.meta_api_diagnostic_test_objects to authenticated;
grant select, insert, update, delete on public.social_campaigns, public.social_ad_sets, public.social_ads, public.social_posts to authenticated;
grant all on public.social_connections, public.social_pages, public.social_ad_accounts, public.social_custom_audiences, public.social_campaigns, public.social_ad_sets, public.social_ads, public.social_posts, public.social_insights, public.social_lead_forms, public.social_lead_submissions, public.meta_api_diagnostics, public.meta_api_diagnostic_test_objects to service_role;

